# 10. lib/gemini.ts

```ts
import { GoogleGenerativeAI } from "@google/generative-ai";

const apiKey = process.env.GEMINI_API_KEY;

if (!apiKey) {
  throw new Error("Missing GEMINI_API_KEY in .env.local");
}

const genAI = new GoogleGenerativeAI(apiKey);

export const geminiModel = genAI.getGenerativeModel({
  model: "gemini-1.5-flash"
});

export async function askGemini(prompt: string) {
  const result = await geminiModel.generateContent(prompt);
  const response = await result.response;
  return response.text();
}
```

---

# 11. lib/agents.ts

```ts
import { askGemini } from "./gemini";
import { AI_SYLLABUS } from "./syllabus";

export type StudentProfile = {
  name: string;
  age: string;
  background: string;
  goals: string;
  experienceLevel: string;
  knownTopics: string;
};

export async function supervisorAgent(output: string, task: string) {
  const prompt = `
You are a Supervisor Agent for an AI tutoring platform.
Your job is to review the output of another agent and ensure it is:
- correct
- clear
- educational
- suitable for the student's level
- in English only

Task:
${task}

Agent Output:
${output}

Return JSON with:
{
  "approved": true/false,
  "feedback": "short feedback",
  "improvedOutput": "improved version if needed, otherwise original"
}
`;
  const text = await askGemini(prompt);
  return safeJsonParse(text);
}

export async function courseCreatorAgent(profile: StudentProfile) {
  const prompt = `
You are a Course Creator Agent for an AI tutor app.

Student profile:
${JSON.stringify(profile, null, 2)}

Available syllabus topics:
${AI_SYLLABUS.map((t, i) => `${i + 1}. ${t}`).join("\n")}

Your task:
1. Estimate the student's current AI skill level.
2. Identify knowledge gaps.
3. Build a personalized learning plan.
4. Sort lessons from easiest to hardest.
5. Recommend first lesson.
6. Everything must be in English.

Return JSON only:
{
  "studentLevel": "Beginner | Intermediate | Advanced",
  "knowledgeGaps": ["..."],
  "recommendedTopics": ["..."],
  "learningPlan": [
    {
      "title": "...",
      "reason": "...",
      "difficulty": "easy | medium | hard"
    }
  ],
  "firstLesson": "..."
}
`;

  const raw = await askGemini(prompt);
  const reviewed = await supervisorAgent(raw, "Review course creation output");
  return safeJsonParse(reviewed?.improvedOutput || raw);
}

export async function teacherAgent(profile: StudentProfile, topic: string) {
  const prompt = `
You are a Teacher Agent in an AI tutor app.

Teach the topic: "${topic}"

Student profile:
${JSON.stringify(profile, null, 2)}

Instructions:
- Explain clearly in English
- Adapt to the student's experience level
- Include definitions
- Include real-world examples
- Include simple analogies
- Include a short recap
- Include 3 reflection questions
- Format in markdown

Return only the lesson content.
`;
  const raw = await askGemini(prompt);
  const reviewed = await supervisorAgent(raw, `Review lesson for topic: ${topic}`);
  return reviewed?.improvedOutput || raw;
}

export async function invigilatorAgent(profile: StudentProfile, topic: string) {
  const prompt = `
You are an Invigilator Agent in an AI tutor app.

Student profile:
${JSON.stringify(profile, null, 2)}

Topic:
${topic}

Create an assignment in English that tests understanding of the lesson.

Return JSON only:
{
  "title": "...",
  "instructions": "...",
  "questions": [
    {
      "type": "short_answer",
      "question": "..."
    },
    {
      "type": "scenario",
      "question": "..."
    },
    {
      "type": "practical_prompting",
      "question": "..."
    }
  ]
}
`;
  const raw = await askGemini(prompt);
  const reviewed = await supervisorAgent(raw, `Review assignment for topic: ${topic}`);
  return safeJsonParse(reviewed?.improvedOutput || raw);
}

export async function gradingAgent(
  profile: StudentProfile,
  topic: string,
  assignment: unknown,
  answers: string[]
) {
  const prompt = `
You are an Invigilator/Grading Agent.

Student profile:
${JSON.stringify(profile, null, 2)}

Topic:
${topic}

Assignment:
${JSON.stringify(assignment, null, 2)}

Student answers:
${JSON.stringify(answers, null, 2)}

Grade the answers fairly based on:
- accuracy
- clarity
- reasoning
- practical AI understanding

Return JSON only:
{
  "score": 0,
  "maxScore": 100,
  "feedback": "...",
  "strengths": ["..."],
  "improvements": ["..."],
  "nextRecommendedTopic": "..."
}
`;
  const raw = await askGemini(prompt);
  const reviewed = await supervisorAgent(raw, `Review grading for topic: ${topic}`);
  return safeJsonParse(reviewed?.improvedOutput || raw);
}

function safeJsonParse(input: string) {
  try {
    const cleaned = input
      .replace(/```json/g, "")
      .replace(/```/g, "")
      .trim();
    return JSON.parse(cleaned);
  } catch {
    return {
      approved: true,
      feedback: "Fallback parse used",
      improvedOutput: input
    };
  }
}
```

