# 12. app/api/assess/route.ts

```ts
import { NextResponse } from "next/server";
import { courseCreatorAgent } from "@/lib/agents";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const result = await courseCreatorAgent(body);
    return NextResponse.json(result);
  } catch (error) {
    return NextResponse.json(
      { error: "Failed to assess student profile", details: String(error) },
      { status: 500 }
    );
  }
}
```

