# 18. components/StudentProfileForm.tsx

```tsx
"use client";

import { useState } from "react";

type Props = {
  onSubmit: (data: {
    name: string;
    age: string;
    background: string;
    goals: string;
    experienceLevel: string;
    knownTopics: string;
  }) => void;
  loading: boolean;
};

export default function StudentProfileForm({ onSubmit, loading }: Props) {
  const [form, setForm] = useState({
    name: "",
    age: "",
    background: "",
    goals: "",
    experienceLevel: "Beginner",
    knownTopics: ""
  });

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6">
      <h2 className="mb-4 text-xl font-semibold">Student Profile</h2>

      <div className="grid gap-4 md:grid-cols-2">
        <input
          className="rounded-lg p-3"
          placeholder="Name"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
        />
        <input
          className="rounded-lg p-3"
          placeholder="Age"
          value={form.age}
          onChange={(e) => setForm({ ...form, age: e.target.value })}
        />
        <textarea
          className="rounded-lg p-3 md:col-span-2"
          placeholder="Background"
          value={form.background}
          onChange={(e) => setForm({ ...form, background: e.target.value })}
        />
        <textarea
          className="rounded-lg p-3 md:col-span-2"
          placeholder="Goals"
          value={form.goals}
          onChange={(e) => setForm({ ...form, goals: e.target.value })}
        />
        <select
          className="rounded-lg p-3"
          value={form.experienceLevel}
          onChange={(e) => setForm({ ...form, experienceLevel: e.target.value })}
        >
          <option>Beginner</option>
          <option>Intermediate</option>
          <option>Advanced</option>
        </select>
        <input
          className="rounded-lg p-3"
          placeholder="Known Topics (comma separated)"
          value={form.knownTopics}
          onChange={(e) => setForm({ ...form, knownTopics: e.target.value })}
        />
      </div>

      <button
        onClick={() => onSubmit(form)}
        disabled={loading}
        className="mt-4 rounded-lg bg-cyan-500 px-4 py-2 font-semibold text-black hover:bg-cyan-400 disabled:opacity-50"
      >
        {loading ? "Analyzing..." : "Generate Learning Plan"}
      </button>
    </div>
  );
}
```

