# 19. components/LearningPlanCard.tsx

```tsx
type PlanItem = {
  title: string;
  reason: string;
  difficulty: string;
};

type Props = {
  plan: {
    studentLevel: string;
    knowledgeGaps: string[];
    recommendedTopics: string[];
    learningPlan: PlanItem[];
    firstLesson: string;
  };
  onSelectLesson: (topic: string) => void;
};

export default function LearningPlanCard({ plan, onSelectLesson }: Props) {
  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6">
      <h2 className="text-xl font-semibold text-cyan-400">Personalized Learning Plan</h2>
      <p className="mt-2 text-sm text-slate-300">
        Detected Level: <span className="font-bold">{plan.studentLevel}</span>
      </p>

      <div className="mt-4">
        <h3 className="font-semibold">Knowledge Gaps</h3>
        <ul className="mt-2 list-disc pl-5 text-slate-300">
          {plan.knowledgeGaps?.map((gap, i) => <li key={i}>{gap}</li>)}
        </ul>
      </div>

      <div className="mt-4">
        <h3 className="font-semibold">Recommended Topics</h3>
        <div className="mt-2 flex flex-wrap gap-2">
          {plan.recommendedTopics?.map((topic, i) => (
            <button
              key={i}
              onClick={() => onSelectLesson(topic)}
              className="rounded-full bg-slate-800 px-3 py-1 text-sm hover:bg-cyan-500 hover:text-black"
            >
              {topic}
            </button>
          ))}
        </div>
      </div>

      <div className="mt-6">
        <h3 className="font-semibold">Learning Sequence</h3>
        <div className="mt-3 space-y-3">
          {plan.learningPlan?.map((item, i) => (
            <div key={i} className="rounded-xl border border-slate-700 p-4">
              <div className="flex items-center justify-between">
                <h4 className="font-semibold">{item.title}</h4>
                <span className="text-xs uppercase text-cyan-400">{item.difficulty}</span>
              </div>
              <p className="mt-1 text-sm text-slate-300">{item.reason}</p>
              <button
                onClick={() => onSelectLesson(item.title)}
                className="mt-3 rounded-lg bg-cyan-500 px-3 py-2 text-sm font-semibold text-black"
              >
                Start Lesson
              </button>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-6 rounded-xl bg-slate-800 p-4">
        <p className="text-sm text-slate-300">Recommended first lesson</p>
        <p className="font-semibold text-cyan-400">{plan.firstLesson}</p>
      </div>
    </div>
  );
}
```

