# 21. components/AssignmentPanel.tsx

```tsx
"use client";

import { useState } from "react";

type Question = {
  type: string;
  question: string;
};

type Assignment = {
  title: string;
  instructions: string;
  questions: Question[];
};

type GradeResult = {
  score: number;
  maxScore: number;
  feedback: string;
  strengths: string[];
  improvements: string[];
  nextRecommendedTopic: string;
};

type Props = {
  assignment: Assignment;
  onSubmit: (answers: string[]) => void;
  loading: boolean;
  gradeResult: GradeResult | null;
};

export default function AssignmentPanel({
  assignment,
  onSubmit,
  loading,
  gradeResult
}: Props) {
  const [answers, setAnswers] = useState<string[]>(
    assignment.questions.map(() => "")
  );

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6">
      <h2 className="text-xl font-semibold text-cyan-400">{assignment.title}</h2>
      <p className="mt-2 text-slate-300">{assignment.instructions}</p>

      <div className="mt-6 space-y-4">
        {assignment.questions.map((q, i) => (
          <div key={i} className="rounded-xl border border-slate-700 p-4">
            <p className="font-medium">{i + 1}. {q.question}</p>
            <p className="mt-1 text-xs uppercase text-slate-400">{q.type}</p>
            <textarea
              className="mt-3 w-full rounded-lg p-3"
              rows={4}
              value={answers[i]}
              onChange={(e) => {
                const updated = [...answers];
                updated[i] = e.target.value;
                setAnswers(updated);
              }}
            />
          </div>
        ))}
      </div>

      <button
        onClick={() => onSubmit(answers)}
        disabled={loading}
        className="mt-4 rounded-lg bg-cyan-500 px-4 py-2 font-semibold text-black disabled:opacity-50"
      >
        {loading ? "Grading..." : "Submit Assignment"}
      </button>

      {gradeResult && (
        <div className="mt-6 rounded-xl border border-cyan-700 bg-slate-800 p-4">
          <h3 className="text-lg font-semibold text-cyan-400">
            Score: {gradeResult.score}/{gradeResult.maxScore}
          </h3>
          <p className="mt-2 text-slate-300">{gradeResult.feedback}</p>

          <div className="mt-4">
            <h4 className="font-semibold">Strengths</h4>
            <ul className="list-disc pl-5 text-slate-300">
              {gradeResult.strengths?.map((s, i) => <li key={i}>{s}</li>)}
            </ul>
          </div>

          <div className="mt-4">
            <h4 className="font-semibold">Improvements</h4>
            <ul className="list-disc pl-5 text-slate-300">
              {gradeResult.improvements?.map((s, i) => <li key={i}>{s}</li>)}
            </ul>
          </div>

          <div className="mt-4">
