# 22. app/page.tsx

```tsx
"use client";

import { useState } from "react";
import Header from "@/components/Header";
import StudentProfileForm from "@/components/StudentProfileForm";
import LearningPlanCard from "@/components/LearningPlanCard";
import LessonViewer from "@/components/LessonViewer";
import AssignmentPanel from "@/components/AssignmentPanel";

type Profile = {
  name: string;
  age: string;
  background: string;
  goals: string;
  experienceLevel: string;
  knownTopics: string;
};

type Plan = {
  studentLevel: string;
  knowledgeGaps: string[];
  recommendedTopics: string[];
  learningPlan: {
    title: string;
    reason: string;
    difficulty: string;
  }[];
  firstLesson: string;
};

type Assignment = {
  title: string;
  instructions: string;
  questions: {
    type: string;
    question: string;
  }[];
};

type GradeResult = {
  score: number;
  maxScore: number;
  feedback: string;
  strengths: string[];
  improvements: string[];
  nextRecommendedTopic: string;
};

export default function HomePage() {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [plan, setPlan] = useState<Plan | null>(null);
  const [selectedTopic, setSelectedTopic] = useState("");
  const [lesson, setLesson] = useState("");
  const [assignment, setAssignment] = useState<Assignment | null>(null);
  const [gradeResult, setGradeResult] = useState<GradeResult | null>(null);

  const [loadingPlan, setLoadingPlan] = useState(false);
  const [loadingLesson, setLoadingLesson] = useState(false);
  const [loadingAssignment, setLoadingAssignment] = useState(false);
  const [loadingGrade, setLoadingGrade] = useState(false);

  async function handleProfileSubmit(data: Profile) {
    setLoadingPlan(true);
    setProfile(data);
    setLesson("");
    setAssignment(null);
    setGradeResult(null);

    const res = await fetch("/api/plan", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(data)
    });

    const json = await res.json();
    setPlan(json);
    setSelectedTopic(json.firstLesson || "");
    setLoadingPlan(false);
  }

  async function handleSelectLesson(topic: string) {
    if (!profile) return;
    setSelectedTopic(topic);
    setLesson("");
    setAssignment(null);
    setGradeResult(null);
    setLoadingLesson(true);

    const res = await fetch("/api/lesson", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ profile, topic })
    });

    const json = await res.json();
    setLesson(json.lesson);
    setLoadingLesson(false);
  }

  async function handleGenerateAssignment() {
    if (!profile || !selectedTopic) return;
    setLoadingAssignment(true);
    setGradeResult(null);

    const res = await fetch("/api/assignment", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ profile, topic: selectedTopic })
    });

    const json = await res.json();
    setAssignment(json);
    setLoadingAssignment(false);
  }

  async function handleGradeAssignment(answers: string[]) {
    if (!profile || !selectedTopic || !assignment) return;
    setLoadingGrade(true);

    const res = await fetch("/api/grade", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        profile,
        topic: selectedTopic,
        assignment,
        answers
      })
    });

    const json = await res.json();
    setGradeResult(json);
    setLoadingGrade(false);
  }

  return (
    <main className="min-h-screen bg-slate-950">
      <Header />

      <div className="mx-auto max-w-6xl space-y-6 px-6 py-8">
        <StudentProfileForm onSubmit={handleProfileSubmit} loading={loadingPlan} />

        {plan && (
          <LearningPlanCard plan={plan} onSelectLesson={handleSelectLesson} />
        )}

        {selectedTopic && !lesson && loadingLesson && (
          <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6">
            Loading lesson for <span className="text-cyan-400">{selectedTopic}</span>...
          </div>
        )}

        {lesson && (
          <LessonViewer
            lesson={lesson}
            topic={selectedTopic}
            onGenerateAssignment={handleGenerateAssignment}
            loading={loadingAssignment}
          />
        )}

        {assignment && (
          <AssignmentPanel
            assignment={assignment}
            onSubmit={handleGradeAssignment}
            loading={loadingGrade}
            gradeResult={gradeResult}
          />
        )}
      </div>
    </main>
  );
}
```

