  SENTRY_DSN: z.string().optional().default(""),
  POSTHOG_KEY: z.string().optional().default(""),
  POSTHOG_HOST: z.string().optional().default("")
});

export type AppEnv = z.infer<typeof envSchema>;

export function getEnv(): AppEnv {
