export function extractJson(text: string): string {
  return text.replace(/```json/g, "").replace(/```/g, "").trim();
}

export function safeJsonParse<T>(text: string): T {
  const cleaned = extractJson(text);
  return JSON.parse(cleaned) as T;
}
