import type {
  Assignment,
  CoursePlan,
  GradeResult,
  Lesson,
  StudentProfile,
  TopicSlug,
  AgentReview
} from "@ai-tutor/types";
import {
  buildAssignmentPrompt,
  buildCourseCreatorPrompt,
  buildGradingPrompt,
  buildSupervisorPrompt,
  buildTeacherPrompt
} from "@ai-tutor/prompts";
import { generateText } from "./gemini";
import { safeJsonParse } from "./json";
import {
  AgentReviewSchema,
  AssignmentSchema,
  CoursePlanSchema,
  GradeResultSchema,
  LessonSchema
} from "./schemas";

export async function runCourseCreatorAgent(profile: StudentProfile): Promise<CoursePlan> {
  const raw = await generateText(buildCourseCreatorPrompt(profile), "flash");
  const reviewed = await runSupervisorAgent(raw, "course_creator");
  const parsed = CoursePlanSchema.parse(reviewed.improvedOutput ?? safeJsonParse(raw));
  return parsed;
}

export async function runTeacherAgent(profile: StudentProfile, topicSlug: TopicSlug): Promise<Lesson> {
  const raw = await generateText(buildTeacherPrompt(profile, topicSlug), "flash");
  const reviewed = await runSupervisorAgent(raw, "teacher");
  const parsed = LessonSchema.parse(reviewed.improvedOutput ?? safeJsonParse(raw));
  return parsed;
}

export async function runInvigilatorAgent(
  profile: StudentProfile,
  topicSlug: TopicSlug
): Promise<Assignment> {
  const raw = await generateText(buildAssignmentPrompt(profile, topicSlug), "flash");
  const reviewed = await runSupervisorAgent(raw, "invigilator");
  const parsed = AssignmentSchema.parse(reviewed.improvedOutput ?? safeJsonParse(raw));
  return parsed;
}

export async function runGradingAgent(
  profile: StudentProfile,
  topicSlug: TopicSlug,
  assignment: Assignment,
  answers: string[]
): Promise<GradeResult> {
  const raw = await generateText(buildGradingPrompt(profile, topicSlug, assignment, answers), "pro");
  const reviewed = await runSupervisorAgent(raw, "grading");
  const parsed = GradeResultSchema.parse(reviewed.improvedOutput ?? safeJsonParse(raw));
  return parsed;
}

export async function runSupervisorAgent(rawOutput: string, taskName: string): Promise<AgentReview> {
  const raw = await generateText(buildSupervisorPrompt(rawOutput, taskName), "flash");
  const parsed = AgentReviewSchema.parse(safeJsonParse(raw));
  return parsed;
}
