"use client";

import { useEffect, useState } from "react";
import Header from "../../components/Header";
import Card from "../../components/Card";
import SectionTitle from "../../components/SectionTitle";
import ProfileForm from "../../components/ProfileForm";
import PlanCard from "../../components/PlanCard";
import LessonCard from "../../components/LessonCard";
import AssignmentCard from "../../components/AssignmentCard";
import ProgressCard from "../../components/ProgressCard";
import { getUserId } from "../../lib/storage";
import { apiFetch } from "../../lib/api";

export default function DashboardPage() {
  const [userId, setUserId] = useState<string | null>(null);
  const [profile, setProfile] = useState<any>(null);
  const [plan, setPlan] = useState<any>(null);
  const [lesson, setLesson] = useState<any>(null);
  const [assignment, setAssignment] = useState<any>(null);
  const [progress, setProgress] = useState<any>(null);
  const [loadingPlan, setLoadingPlan] = useState(false);

  useEffect(() => {
    const id = getUserId();
    setUserId(id);
  }, []);

  useEffect(() => {
    if (!userId) return;
    refreshAll(userId);
  }, [userId]);

  async function refreshAll(id: string) {
    try {
      const p = await apiFetch(`/students/profile/${id}`);
      setProfile(p);

      const latestPlan = await apiFetch(`/plans/${id}`).catch(() => null);
      setPlan(latestPlan);

      const prog = await apiFetch(`/progress/${id}`).catch(() => null);
      setProgress(prog);
    } catch {
      // ignore for initial empty state
    }
  }

  async function generatePlan() {
    if (!userId) return;
    setLoadingPlan(true);

    try {
      const created = await apiFetch("/plans", {
        method: "POST",
        body: JSON.stringify({ userId })
      });
      setPlan(created);
    } finally {
      setLoadingPlan(false);
    }
  }

  async function handleLessonCreated(lessonId: string) {
    const data = await apiFetch(`/lessons/${lessonId}`);
    setLesson(data);
    setAssignment(null);
    if (userId) {
      const prog = await apiFetch(`/progress/${userId}`).catch(() => null);
      setProgress(prog);
    }
  }

  async function handleAssignmentCreated(assignmentId: string) {
    const data = await apiFetch(`/assignments/${assignmentId}`);
    setAssignment({
      ...data,
      questions: Array.isArray(data.questions) ? data.questions : []
    });
  }

  if (!userId) {
    return (
      <main className="min-h-screen bg-slate-950">
        <Header />
        <div className="mx-auto max-w-4xl px-6 py-10">
          <Card>
            <SectionTitle
              title="No active user"
              subtitle="Create an account on the home page first."
            />
          </Card>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950">
      <Header />

      <div className="mx-auto max-w-6xl space-y-6 px-6 py-8">
        {!profile ? (
          <ProfileForm userId={userId} onCreated={() => refreshAll(userId)} />
        ) : (
          <Card>
            <SectionTitle
              title={`Welcome, ${profile.fullName}`}
              subtitle="Your personalized AI learning workspace"
            />
            <div className="grid gap-2 text-sm text-slate-300 md:grid-cols-2">
              <p><span className="font-semibold">Level:</span> {profile.selfReportedLevel}</p>
              <p><span className="font-semibold">Language:</span> {profile.preferredLanguage}</p>
              <p><span className="font-semibold">Age range:</span> {profile.ageRange}</p>
              <p><span className="font-semibold">Learning style:</span> {profile.preferredLearningStyle}</p>
            </div>

            <button
              onClick={generatePlan}
              disabled={loadingPlan}
              className="mt-4 rounded-lg bg-cyan-500 px-4 py-3 font-semibold text-black hover:bg-cyan-400 disabled:opacity-50"
            >
              {loadingPlan ? "Generating..." : "Generate Learning Plan"}
            </button>
          </Card>
        )}

        <PlanCard
          userId={userId}
          plan={plan}
          onLessonCreated={handleLessonCreated}
        />

        <LessonCard
          userId={userId}
          lesson={lesson}
          onAssignmentCreated={handleAssignmentCreated}
        />

        <AssignmentCard
          userId={userId}
          assignment={assignment}
        />

        <ProgressCard progress={progress} />
      </div>
    </main>
  );
}
