    setLoading(true);
    setMessage("");

    try {
      const result = await apiFetch<{
        id: string;
        email: string;
        role: string;
        accessToken: string;
      }>("/auth/signup", {
        method: "POST",
        body: JSON.stringify(form)
      });

      setSession({
        userId: result.id,
        accessToken: result.accessToken,
        role: result.role
      });

