import { Injectable, NotFoundException } from "@nestjs/common";
import { DatabaseService } from "../database/database.service";

@Injectable()
export class PromptsService {
  constructor(private readonly db: DatabaseService) {}

  async getAll() {
    return this.db.client.promptTemplate.findMany({
      orderBy: { createdAt: "desc" }
    });
  }

  async getActive(agentType: "course_creator" | "teacher" | "invigilator" | "supervisor" | "progress_coach") {
    const prompt = await this.db.client.promptTemplate.findFirst({
      where: {
        agentType,
        active: true
      },
      orderBy: {
        createdAt: "desc"
      }
    });

    if (!prompt) {
      throw new NotFoundException(`No active prompt found for ${agentType}`);
    }

    return prompt;
  }

  async activate(promptId: string) {
    const current = await this.db.client.promptTemplate.findUnique({
      where: { id: promptId }
    });

    if (!current) {
      throw new NotFoundException("Prompt template not found");
    }

    await this.db.client.promptTemplate.updateMany({
      where: { agentType: current.agentType },
      data: { active: false }
    });

    return this.db.client.promptTemplate.update({
      where: { id: promptId },
      data: { active: true }
    });
  }

  async create(input: {
    agentType: "course_creator" | "teacher" | "invigilator" | "supervisor" | "progress_coach";
    version: string;
    promptText: string;
    responseSchema: unknown;
    active?: boolean;
  }) {
    return this.db.client.promptTemplate.create({
      data: {
        agentType: input.agentType,
        version: input.version,
        promptText: input.promptText,
        responseSchema: input.responseSchema as any,
        active: input.active ?? false
      }
    });
  }
}
