import { GoogleGenerativeAI } from "@google/generative-ai";
import { getEnv } from "@ai-tutor/config";
import { withRetry } from "./retry";

const env = getEnv();

const genAI = new GoogleGenerativeAI(env.GEMINI_API_KEY);

export const flashModel = genAI.getGenerativeModel({
  model: env.GEMINI_MODEL_FLASH
});

export const proModel = genAI.getGenerativeModel({
  model: env.GEMINI_MODEL_PRO
});

export async function generateText(prompt: string, model: "flash" | "pro" = "flash") {
  const selected = model === "pro" ? proModel : flashModel;

  return withRetry(async () => {
    const result = await selected.generateContent(prompt);
    const response = await result.response;
    const text = response.text();

    if (!text || !text.trim()) {
      throw new Error("Empty model response");
    }

    return text;
  });
}

export async function generateTextWithFallback(prompt: string, preferred: "flash" | "pro" = "flash") {
  try {
    return await generateText(prompt, preferred);
  } catch (error) {
    if (preferred === "flash") {
      return generateText(prompt, "pro");
    }
    throw error;
  }
}
```

