    return this.db.client.coursePlan.create({
      data: {
        studentProfileId: profile.id,
        studentLevel: plan.studentLevel,
        knowledgeGaps: plan.knowledgeGaps,
        recommendedTopics: plan.recommendedTopics.map(toPrismaTopicSlug),
