import { Body, Controller, Post } from "@nestjs/common";
import { assignmentQueue, gradingQueue } from "../../common/queue";
import { DatabaseService } from "../database/database.service";
import { CreateAssignmentDto } from "./dto/create-assignment.dto";
import { SubmitAssignmentDto } from "./dto/submit-assignment.dto";

@Controller("assignments-async")
export class AssignmentsAsyncController {
  constructor(private readonly db: DatabaseService) {}

  @Post()
  async enqueueAssignment(@Body() dto: CreateAssignmentDto) {
    const profile = await this.db.client.studentProfile.findUnique({
      where: { userId: dto.userId }
    });

    if (!profile) {
      return { error: "Student profile not found" };
    }

    const job = await assignmentQueue.add("generate-assignment", {
      studentProfileId: profile.id,
      topicSlug: dto.topicSlug,
      lessonId: dto.lessonId ?? null
    });

    return {
      queued: true,
      jobId: job.id
    };
  }

  @Post("submit")
  async enqueueGrading(@Body() dto: SubmitAssignmentDto) {
    const profile = await this.db.client.studentProfile.findUnique({
      where: { userId: dto.userId }
    });

    if (!profile) {
      return { error: "Student profile not found" };
    }

    const assignment = await this.db.client.assignment.findUnique({
      where: { id: dto.assignmentId }
    });

    if (!assignment) {
      return { error: "Assignment not found" };
    }

    const submission = await this.db.client.submission.create({
      data: {
        assignmentId: assignment.id,
        studentProfileId: profile.id,
        answers: dto.answers as any
      }
    });

    const job = await gradingQueue.add("grade-submission", {
      submissionId: submission.id
    });

    return {
      queued: true,
      jobId: job.id,
      submissionId: submission.id
    };
  }
}
