import { Injectable, BadRequestException, UnauthorizedException } from "@nestjs/common";
import { DatabaseService } from "../database/database.service";
import * as bcrypt from "bcryptjs";
import { JwtService } from "@nestjs/jwt";
import { getEnv } from "@ai-tutor/config";

const env = getEnv();

@Injectable()
export class AuthService {
  constructor(
    private readonly db: DatabaseService,
    private readonly jwtService: JwtService
  ) {}

  async signUp(email: string, password: string, role: "student" | "admin" | "content_manager" | "ai_ops") {
    const existing = await this.db.client.user.findUnique({
      where: { email }
    });

    if (existing) {
      throw new BadRequestException("Email already exists");
    }

    const passwordHash = await bcrypt.hash(password, 12);

    const user = await this.db.client.user.create({
      data: {
        email,
        passwordHash,
        role
      }
    });

    const tokens = await this.issueTokens(user.id, user.email, user.role);
    await this.storeRefreshToken(user.id, tokens.refreshToken);

    return {
      id: user.id,
      email: user.email,
      role: user.role,
      ...tokens
    };
  }

  async login(email: string, password: string) {
    const user = await this.db.client.user.findUnique({
      where: { email }
    });

    if (!user) {
      throw new UnauthorizedException("Invalid credentials");
    }

    const isValid = await bcrypt.compare(password, user.passwordHash);

    if (!isValid) {
      throw new UnauthorizedException("Invalid credentials");
    }

    const tokens = await this.issueTokens(user.id, user.email, user.role);
    await this.storeRefreshToken(user.id, tokens.refreshToken);

    return {
      id: user.id,
      email: user.email,
      role: user.role,
      ...tokens
    };
  }

  async refresh(userId: string, refreshToken: string) {
    const user = await this.db.client.user.findUnique({
      where: { id: userId }
    });

    if (!user || !user.refreshTokenHash) {
      throw new UnauthorizedException("Access denied");
    }

    const refreshMatches = await bcrypt.compare(refreshToken, user.refreshTokenHash);

    if (!refreshMatches) {
      throw new UnauthorizedException("Invalid refresh token");
    }

    const tokens = await this.issueTokens(user.id, user.email, user.role);
    await this.storeRefreshToken(user.id, tokens.refreshToken);

    return {
      id: user.id,
      email: user.email,
      role: user.role,
      ...tokens
    };
  }

  async logout(userId: string) {
    await this.db.client.user.update({
      where: { id: userId },
      data: {
        refreshTokenHash: null
      }
    });

    return { loggedOut: true };
  }

  async me(userId: string) {
    const user = await this.db.client.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        email: true,
        role: true,
        createdAt: true
      }
    });

    return user;
  }

  private async issueTokens(userId: string, email: string, role: string) {
    const accessToken = await this.jwtService.signAsync(
      {
        sub: userId,
        email,
        role
      },
      {
        secret: env.JWT_SECRET,
        expiresIn: "15m"
      }
    );

    const refreshToken = await this.jwtService.signAsync(
      {
        sub: userId,
        email,
        role
      },
      {
        secret: env.JWT_REFRESH_SECRET,
        expiresIn: "7d"
      }
    );

    return { accessToken, refreshToken };
  }

  private async storeRefreshToken(userId: string, refreshToken: string) {
    const refreshTokenHash = await bcrypt.hash(refreshToken, 12);

    await this.db.client.user.update({
      where: { id: userId },
      data: {
        refreshTokenHash
      }
    });
  }
}
