import {
  Body,
  Controller,
  Get,
  Post,
  Req,
  Res,
  UnauthorizedException,
  UseGuards
} from "@nestjs/common";
import { AuthService } from "./auth.service";
import { SignUpDto } from "./dto/signup.dto";
import { LoginDto } from "./dto/login.dto";
import { JwtAuthGuard } from "./guards/jwt-auth.guard";
import { CurrentUser } from "./decorators/current-user.decorator";
import { Request, Response } from "express";
import { setAuthCookies, clearAuthCookies } from "./utils/cookies";
import { extractRefreshToken } from "./utils/token-extractor";
import { JwtService } from "@nestjs/jwt";
import { getEnv } from "@ai-tutor/config";

const env = getEnv();

@Controller("auth")
export class AuthController {
  constructor(
    private readonly authService: AuthService,
    private readonly jwtService: JwtService
  ) {}

  @Post("signup")
  async signUp(@Body() dto: SignUpDto, @Res({ passthrough: true }) res: Response) {
    const result = await this.authService.signUp(dto.email, dto.password, dto.role);
    setAuthCookies(res, result.accessToken, result.refreshToken);

    return {
      id: result.id,
      email: result.email,
      role: result.role
    };
  }

  @Post("login")
  async login(@Body() dto: LoginDto, @Res({ passthrough: true }) res: Response) {
    const result = await this.authService.login(dto.email, dto.password);
    setAuthCookies(res, result.accessToken, result.refreshToken);

    return {
      id: result.id,
      email: result.email,
      role: result.role
    };
  }

  @Post("refresh")
  async refresh(@Req() req: Request, @Res({ passthrough: true }) res: Response) {
    const refreshToken = extractRefreshToken(req);

    if (!refreshToken) {
      throw new UnauthorizedException("Missing refresh token");
    }

    let payload: any;

    try {
      payload = await this.jwtService.verifyAsync(refreshToken, {
        secret: env.JWT_REFRESH_SECRET
      });
    } catch {
      throw new UnauthorizedException("Invalid refresh token");
    }

    const result = await this.authService.refresh(payload.sub, refreshToken);
    setAuthCookies(res, result.accessToken, result.refreshToken);

    return {
      id: result.id,
      email: result.email,
      role: result.role
    };
  }

  @UseGuards(JwtAuthGuard)
  @Post("logout")
  async logout(
    @CurrentUser() user: { userId: string },
    @Res({ passthrough: true }) res: Response
  ) {
    await this.authService.logout(user.userId);
    clearAuthCookies(res);
    return { loggedOut: true };
  }

  @UseGuards(JwtAuthGuard)
  @Get("me")
  async me(@CurrentUser() user: { userId: string }) {
    return this.authService.me(user.userId);
  }
}
