# 1. BETTER DISTRIBUTED RATE LIMITING

Statt In-Memory-Rate-Limit bauen wir ein Redis-basiertes Limit.  
Das funktioniert deutlich besser mit mehreren API-Instanzen.

---

## 210) `apps/api/src/common/middleware/rate-limit.middleware.ts` — ERSETZEN

```ts
import { Injectable, NestMiddleware } from "@nestjs/common";
import { redis } from "../cache";

const WINDOW_SECONDS = 60;
const MAX_REQUESTS = 120;

@Injectable()
export class RateLimitMiddleware implements NestMiddleware {
  async use(req: any, res: any, next: () => void) {
    const ip =
      req.headers["x-forwarded-for"]?.split(",")[0]?.trim() ||
      req.ip ||
      req.connection?.remoteAddress ||
      "unknown";

    const key = `rate_limit:${ip}`;
    const count = await redis.incr(key);

    if (count === 1) {
      await redis.expire(key, WINDOW_SECONDS);
    }

    if (count > MAX_REQUESTS) {
      return res.status(429).json({
        success: false,
        error: {
          statusCode: 429,
          message: "Too many requests",
          timestamp: new Date().toISOString(),
          path: req.originalUrl
        }
      });
    }

    next();
  }
}
```

