export function estimateModelCost(input: {
  modelUsed?: string | null;
  tokenUsage?: number | null;
}) {
  const tokens = input.tokenUsage ?? 0;
  const model = input.modelUsed ?? "unknown";

  // Placeholder rough pricing model
  const ratesPer1k: Record<string, number> = {
    "gemini-flash": 0.0005,
    "gemini-pro": 0.003,
    unknown: 0
  };

  const rate = ratesPer1k[model] ?? ratesPer1k.unknown;
  return Number(((tokens / 1000) * rate).toFixed(6));
}
