import { Injectable } from "@nestjs/common";
import { DatabaseService } from "../database/database.service";

@Injectable()
export class AdminService {
  constructor(private readonly db: DatabaseService) {}

  async getAgentRuns(limit = 50) {
    return this.db.client.agentRun.findMany({
      orderBy: { createdAt: "desc" },
      take: limit
    });
  }

  async getUsers(limit = 50) {
    return this.db.client.user.findMany({
      orderBy: { createdAt: "desc" },
      take: limit,
      include: {
        studentProfile: true
      }
    });
  }

  async getPromptTemplates() {
    return this.db.client.promptTemplate.findMany({
      orderBy: { createdAt: "desc" }
    });
  }

  async getAnalyticsEvents(limit = 100) {
    return this.db.client.analyticsEvent.findMany({
      orderBy: { createdAt: "desc" },
      take: limit
    });
  }

  async getAgentCostSummary() {
    const runs = await this.db.client.agentRun.findMany({
      select: {
        agentType: true,
        modelUsed: true,
        costEstimate: true,
        tokenUsage: true
      }
    });

    const summary = runs.reduce<Record<string, { totalCost: number; totalTokens: number; count: number }>>(
      (acc, run) => {
        const key = `${run.agentType}:${run.modelUsed ?? "unknown"}`;
        if (!acc[key]) {
          acc[key] = {
            totalCost: 0,
            totalTokens: 0,
            count: 0
          };
        }

        acc[key].totalCost += run.costEstimate ?? 0;
        acc[key].totalTokens += run.tokenUsage ?? 0;
        acc[key].count += 1;

        return acc;
      },
      {}
    );

    return summary;
  }
}
```

