export default function PromptManager({
  prompts,
  onRefresh
}: {
  prompts: any[];
  onRefresh: () => void;
}) {
  const [form, setForm] = useState({
    agentType: "teacher",
    version: "",
    promptText: "",
    responseSchema: "{ \"type\": \"object\" }",
    active: false
  });
  const [loading, setLoading] = useState(false);

  async function handleCreate() {
    setLoading(true);
    try {
      await createPrompt({
        agentType: form.agentType,
        version: form.version,
        promptText: form.promptText,
        responseSchema: JSON.parse(form.responseSchema),
        active: form.active
      });
      onRefresh();
      setForm({
        agentType: "teacher",
        version: "",
        promptText: "",
        responseSchema: "{ \"type\": \"object\" }",
        active: false
      });
    } finally {
      setLoading(false);
    }
  }

  async function handleActivate(promptId: string) {
    setLoading(true);
