            rows={8}
            className="rounded-lg p-3"
            placeholder="Prompt template text with variables like {{studentProfile}}"
            value={form.promptText}
            onChange={(e) => setForm((v) => ({ ...v, promptText: e.target.value }))}
          />

          <textarea
            rows={4}
            className="rounded-lg p-3"
            placeholder="JSON response schema"
            value={form.responseSchema}
            onChange={(e) => setForm((v) => ({ ...v, responseSchema: e.target.value }))}
          />

          <label className="flex items-center gap-2 text-sm text-slate-300">
