      const [runsData, usersData, promptsData, analyticsData, costsData] = await Promise.all([
        fetchAdminAgentRuns(100),
        fetchAdminUsers(100),
        fetchAdminPrompts(),
        fetchAdminAnalytics(100),
        fetchAdminAgentCosts()
      ]);

      setRuns(runsData);
      setUsers(usersData);
      setPrompts(promptsData);
      setAnalytics(analyticsData);
      setCosts(costsData);
